// packages/server/src/config.ts  — the complete v1 env surface
import { z } from 'zod';

export const Env = z.object({
  // ---- REQUIRED, no default, no fallback ----
  DATABASE_URL: z.url({ protocol: /^postgres(ql)?$/ }),
  AUTH_SECRET:  z.string().min(32, 'must be >= 32 chars — run `mcprouter secret`; a per-process random value breaks every additional replica'),
  PUBLIC_URL:   z.url().describe('absolute origin (+optional path) clients reach the hub at; OAuth redirect_uri and the RFC 8707 resource audience are derived from it'),

  // ---- process ----
  NODE_ENV: z.enum(['production','development','test']).default('production'),
  PORT:     z.coerce.number().int().min(1).max(65535).default(3000),
  HOST:     z.string().default('0.0.0.0'),
  SHUTDOWN_TIMEOUT_MS: z.coerce.number().int().positive().default(10_000),

  // ---- storage ----
  DB_POOL_MAX:     z.coerce.number().int().positive().default(10),
  MIGRATE_ON_BOOT: z.stringbool().default(true),
  DATA_DIR:        z.string().default('/app/data'),
  WEB_DIST:        z.string().default('/app/web'),

  // ---- logging / telemetry ----
  LOG_LEVEL:  z.enum(['trace','debug','info','warn','error','fatal']).default('info'),
  LOG_FORMAT: z.enum(['json','pretty']).default('json'),
  LOG_DIR:    z.string().optional(),            // set => pino-roll file sink
  OTEL_EXPORTER_OTLP_ENDPOINT: z.url().optional(), // set => start sdk-node. OTel's own name; we invent nothing.

  // ---- trust boundary knobs ----
  TRUST_PROXY_HOPS:           z.coerce.number().int().min(0).default(0),
  UPSTREAM_ALLOW_PRIVATE_IPS: z.stringbool().default(false), // WARN at boot when true
  STDIO_ENABLED:              z.stringbool().default(true),

  // ---- embeddings (core) ----
  EMBEDDING_PROVIDER: z.enum(['none','openai','azure','gemini']).default('none'),
  EMBEDDING_API_KEY:  z.string().optional(),
  EMBEDDING_BASE_URL: z.url().optional(),
  EMBEDDING_MODEL:    z.string().default('text-embedding-3-small'),
  EMBEDDING_DIM:      z.coerce.number().int().positive().default(1536),
}).superRefine((c, ctx) => {
  if (c.EMBEDDING_PROVIDER !== 'none' && !c.EMBEDDING_API_KEY)
    ctx.addIssue({ code: 'custom', path: ['EMBEDDING_API_KEY'],
      message: `required when EMBEDDING_PROVIDER=${c.EMBEDDING_PROVIDER} (use 'none' for the zero-key hash fallback)` });
});

export type Config = z.infer<typeof Env>;

// same file — parse once, fail loud, never print a value
import { readFileSync } from 'node:fs';

/** Docker `secrets:` / k8s projected volumes deliver secrets as files. FOO_FILE wins over FOO. */
function sourceEnv(src: NodeJS.ProcessEnv = process.env): Record<string, string|undefined> {
  const plain = Object.fromEntries(Object.entries(src).filter(([k]) => !k.endsWith('_FILE')));
  const fromFiles = Object.entries(src)
    .filter(([k, v]) => k.endsWith('_FILE') && v)
    .map(([k, v]) => [k.slice(0, -5), readFileSync(v!, 'utf8').trim()]);
  return { ...plain, ...Object.fromEntries(fromFiles) };
}

const SECRET_KEYS = ['AUTH_SECRET','DATABASE_URL','EMBEDDING_API_KEY'] as const;

export function loadConfig(src?: NodeJS.ProcessEnv): Config {
  const r = Env.safeParse(sourceEnv(src));
  if (!r.success) {
    console.error('MCPRouter cannot start — invalid configuration:\n');
    for (const i of r.error.issues) console.error(`  ${i.path.join('.') || '(env)'}: ${i.message}`);
    console.error('\nSee .env.example. Values are never echoed.');
    process.exit(78); // EX_CONFIG: permanent, do not restart-loop
  }
  // one logger.info({config}) must not exfiltrate the database password
  return Object.defineProperty(r.data, 'toJSON', {
    value: () => ({ ...r.data, ...Object.fromEntries(SECRET_KEYS.map(k => [k, '[redacted]'])) }),
    enumerable: false,
  });
}

// packages/core/src/db/migrate.ts
import { migrate } from 'drizzle-orm/node-postgres/migrator';

const LOCK_ID = 0x6d63_7072; // 'mcpr'

/** Safe to call from every replica at boot: the advisory lock serialises DDL. */
export async function runMigrations(pool: Pool, folder: string): Promise<void> {
  const c = await pool.connect();
  try {
    await c.query('SELECT pg_advisory_lock($1)', [LOCK_ID]);
    await migrate(drizzle(c), { migrationsFolder: folder });
  } finally {
    await c.query('SELECT pg_advisory_unlock($1)', [LOCK_ID]).catch(() => {});
    c.release();
  }
}

/** A pgvector column's dimension is fixed by its migration. Catch the mismatch at boot, not at first search. */
export async function assertEmbeddingDim(db: Db, expected: number): Promise<void> {
  const [row] = await db.execute(sql`SELECT atttypmod AS dim FROM pg_attribute
    WHERE attrelid = 'tool_embeddings'::regclass AND attname = 'embedding'`);
  if (row?.dim !== expected)
    throw new Error(`EMBEDDING_DIM=${expected} but tool_embeddings.embedding is vector(${row?.dim}). `
      + `Changing the dimension needs a migration: pnpm db:generate after editing schema.ts, then redeploy.`);
}

