// static, mounted LAST, after every API family
app.get('/assets/*', serveStatic({ root: cfg.WEB_DIST, onFound: (_p, c) =>
  c.header('Cache-Control', 'public, max-age=31536000, immutable') }));   // vite hashes filenames
app.get('*', async (c, next) => {
  // exclusion list lives here on purpose: adding an API family without updating it
  // serves index.html with a 200 instead of a 404, which is confusing to debug.
  if (/^\/(api|mcp|health|metrics|\.well-known)(\/|$)/.test(c.req.path)) return next();
  return serveStatic({ path: 'index.html', root: cfg.WEB_DIST })(c, next);
});

