// test/e2e/gateway.e2e.ts — the one test that proves the product works.
// Real SDK Client → real built server → real upstream MCP server.
const pg    = await new PostgreSqlContainer('pgvector/pgvector:pg16').start();
const app   = await createApp(loadConfig(testEnv(pg)));     // in-process, no docker exec: ~2s not ~40s
const { url, close } = serve(app);
const key   = await seedAdminKey();

// upstream A: stdio   (node test/fixtures/echo-server.ts)
// upstream B: streamable-http (the same fixture, --http)
await api('POST /api/servers', { name: 'echo', type: 'stdio', command: 'node', args: [FIXTURE] });

const client = new Client({ name: 'e2e', version: '0' });
await client.connect(new StreamableHTTPClientTransport(new URL(`${url}/mcp`), {
  requestInit: { headers: { authorization: `Bearer ${key}` } } }));

expect((await client.listTools()).tools.map(t => t.name)).toContain('echo-echo');
expect(await client.callTool({ name: 'echo-echo', arguments: { s: 'hi' } })).toMatchObject({ content: [{ text: 'hi' }] });

// THE invariant (mcphub CVE afcc72f): disable at list time ⇒ disabled at call time,
// and a hidden tool is indistinguishable from one that never existed.
await api('PATCH /api/servers/echo/tools/echo', { enabled: false });
expect((await client.listTools()).tools.map(t => t.name)).not.toContain('echo-echo');
const hidden  = await client.callTool({ name: 'echo-echo',  arguments: {} }).catch(e => e);
const missing = await client.callTool({ name: 'echo-nope',  arguments: {} }).catch(e => e);
expect(hidden.message).toBe(missing.message);        // byte-identical

// transport shape (legacy era today; the modern-era twin lands beside it)
expect(await rawPost('/mcp', notification)).toMatchObject({ status: 202, body: '' });
expect((await rawGet('/mcp')).status).toBe(405);     // standalone GET stream is not served

// resilience
await killUpstream(); expect(await client.callTool(...)).toBeJsonRpcError();
await restartUpstream(); expect(await client.callTool(...)).toSucceed();
await close(); await pg.stop();

